using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using AcadeGameMaker.Profile;
using NUnit.Framework;

namespace AcadeGameMaker.Tests.EditMode.Profile
{
    // REQ-M5D7K-001..007; AC-M5D7K-001..009. Preservation order and MayPersist proof only.
    public sealed class ProfileLaunchPreservationExecutorV1Tests
    {
        private static readonly DateTimeOffset Utc = new DateTimeOffset(2026, 9, 13, 10, 11, 12, 345, TimeSpan.Zero);
        private const string UtcToken = "20260913T101112345Z";

        [Test] public void AC001_NoIntentReturnsThreeNotRequiredWithoutPortCall()
        {
            WithDirectory(root => { var observation = EmptyObservation(); var port = new Port(); var result = Invoke(root, observation, Select(observation), port); AssertStates(result, ProfileLaunchPreservationStateV1.NotRequired, ProfileLaunchPreservationStateV1.NotRequired, ProfileLaunchPreservationStateV1.NotRequired, true, null); Assert.That(port.Calls, Is.Empty); Assert.That(Directory.Exists(Path.Combine(root, "recovery")), Is.False); });
        }

        [Test] public void AC002_ResolvedOutcomesForwardExactArgumentsInOrder()
        {
            WithDirectory(root => { var observation = ThreeIntentObservation(); var port = new Port { Outcomes = new[] { ProfileQuarantineOutcome.Preserved, ProfileQuarantineOutcome.SourceMissing, ProfileQuarantineOutcome.Preserved } }; var result = Invoke(root + Path.DirectorySeparatorChar, observation, Select(observation), port); CollectionAssert.AreEqual(new[] { "Temp:StaleTemp", "Primary:InvalidPrimary", "Previous:UnsupportedPrevious" }, port.Calls); CollectionAssert.AreEqual(new[] { Path.GetFullPath(root), Path.GetFullPath(root), Path.GetFullPath(root) }, port.Roots); CollectionAssert.AreEqual(new[] { Utc, Utc, Utc }, port.UtcCalls); AssertCandidateEqual(observation.Temp, port.Candidates[0]); AssertCandidateEqual(observation.Primary, port.Candidates[1]); AssertCandidateEqual(observation.Previous, port.Candidates[2]); AssertStates(result, ProfileLaunchPreservationStateV1.Preserved, ProfileLaunchPreservationStateV1.SourceMissing, ProfileLaunchPreservationStateV1.Preserved, true, null); });
        }

        [Test] public void AC003_BothStopOutcomesAtEveryRoleCloseExactPrefix()
        {
            WithDirectory(root => { var observation = ThreeIntentObservation(); var selection = Select(observation); foreach (var failure in new[] { ProfileQuarantineOutcome.FailedBeforeMove, ProfileQuarantineOutcome.MoveOutcomeUncertain }) for (var stop = 0; stop < 3; stop++) { var outcomes = new[] { ProfileQuarantineOutcome.SourceMissing, ProfileQuarantineOutcome.SourceMissing, ProfileQuarantineOutcome.SourceMissing }; outcomes[stop] = failure; var port = new Port { Outcomes = outcomes }; var result = Invoke(root, observation, selection, port); var failureState = failure == ProfileQuarantineOutcome.FailedBeforeMove ? ProfileLaunchPreservationStateV1.FailedBeforeMove : ProfileLaunchPreservationStateV1.MoveOutcomeUncertain; var expected = new[] { ProfileLaunchPreservationStateV1.SourceMissing, ProfileLaunchPreservationStateV1.SourceMissing, ProfileLaunchPreservationStateV1.SourceMissing }; expected[stop] = failureState; for (var later = stop + 1; later < 3; later++) expected[later] = ProfileLaunchPreservationStateV1.NotAttempted; AssertStates(result, expected[0], expected[1], expected[2], false, stop == 0 ? ProfileLoadFileRole.Temp : stop == 1 ? ProfileLoadFileRole.Primary : ProfileLoadFileRole.Previous); Assert.That(port.Calls.Count, Is.EqualTo(stop + 1)); } });
        }

        [Test] public void AC003_LaterNoneRemainsNotRequiredAfterEarlierStop()
        {
            WithDirectory(root => { var observation = new ProfileLaunchObservationBatchV1(InvalidCandidate(ProfileLoadFileRole.Primary), ProfileLoadCandidateV1.Missing(ProfileLoadFileRole.Previous), InvalidCandidate(ProfileLoadFileRole.Temp)); var port = new Port { Outcomes = new[] { ProfileQuarantineOutcome.FailedBeforeMove } }; var result = Invoke(root, observation, Select(observation), port); AssertStates(result, ProfileLaunchPreservationStateV1.FailedBeforeMove, ProfileLaunchPreservationStateV1.NotAttempted, ProfileLaunchPreservationStateV1.NotRequired, false, ProfileLoadFileRole.Temp); Assert.That(port.Calls.Count, Is.EqualTo(1)); });
        }

        [Test] public void AC004_RealFilesUseExactRecoveryNamesAndDoNotRewriteSources()
        {
            WithDirectory(root => { var temp = Encoding.UTF8.GetBytes("stale"); var primary = Encoding.UTF8.GetBytes("{}"); var previous = Encoding.UTF8.GetBytes("{\"schemaVersion\":0}"); File.WriteAllBytes(Path.Combine(root, "profile.tmp.json"), temp); File.WriteAllBytes(Path.Combine(root, "profile.json"), primary); File.WriteAllBytes(Path.Combine(root, "profile.prev.json"), previous); var observation = ProfileLaunchObservationAdapterV1.Observe(root); Assert.That(observation.Previous.DecodeResult.Classification, Is.EqualTo(ProfileCanonicalDecodeClassification.UnsupportedProfileSchema)); var result = ProfileLaunchPreservationExecutorV1.Execute(root, observation, Select(observation), Utc); Assert.That(result.MayPersist, Is.True); CollectionAssert.AreEquivalent(new[] { "profile-stale-temp-" + UtcToken + "-" + Hash8(temp) + ".json", "profile-invalid-primary-" + UtcToken + "-" + Hash8(primary) + ".json", "profile-unsupported-v0-" + UtcToken + "-" + Hash8(previous) + ".json" }, Array.ConvertAll(Directory.GetFiles(Path.Combine(root, "recovery")), Path.GetFileName)); Assert.That(File.Exists(Path.Combine(root, "profile.tmp.json")), Is.False); Assert.That(File.Exists(Path.Combine(root, "profile.json")), Is.False); Assert.That(File.Exists(Path.Combine(root, "profile.prev.json")), Is.False); });
        }

        [Test] public void AC004_UnreadableIntentIsForwardedDeterministically()
        {
            WithDirectory(root => { var observation = new ProfileLaunchObservationBatchV1(ProfileLoadCandidateV1.Unreadable(ProfileLoadFileRole.Primary), ProfileLoadCandidateV1.Missing(ProfileLoadFileRole.Previous), ProfileLoadCandidateV1.Missing(ProfileLoadFileRole.Temp)); var port = new Port { Outcomes = new[] { ProfileQuarantineOutcome.FailedBeforeMove }, FailedSourceUnreadable = true }; var result = Invoke(root, observation, Select(observation), port); CollectionAssert.AreEqual(new[] { "Primary:UnreadablePrimary" }, port.Calls); AssertCandidateEqual(observation.Primary, port.Candidates[0]); Assert.That(port.Returned[0].SourceState, Is.EqualTo(ProfileQuarantineFileState.Unreadable)); AssertStates(result, ProfileLaunchPreservationStateV1.NotRequired, ProfileLaunchPreservationStateV1.FailedBeforeMove, ProfileLaunchPreservationStateV1.NotRequired, false, ProfileLoadFileRole.Primary); });
        }

        [Test] public void AC005_InvalidInputsAndSemanticMismatchMakeZeroCalls()
        {
            WithDirectory(root => { var observation = ThreeIntentObservation(); var selection = Select(observation); var port = new Port(); Assert.Throws<ArgumentException>(() => Invoke(root, default(ProfileLaunchObservationBatchV1), selection, port)); Assert.Throws<ArgumentException>(() => Invoke(root, observation, default(ProfileLoadSelectionPlanV1), port)); var corruptPrimary = Mutate(observation.Primary, "_kind", (ProfileLoadCandidateKind)99); var corruptObservation = new ProfileLaunchObservationBatchV1(corruptPrimary, observation.Previous, observation.Temp); Assert.Throws<ArgumentException>(() => Invoke(root, corruptObservation, selection, port)); Assert.Throws<ArgumentException>(() => Invoke(Path.GetPathRoot(root), observation, selection, port)); Assert.Throws<ArgumentException>(() => ProfileLaunchPreservationExecutorV1.Execute(root, observation, selection, Utc.ToOffset(TimeSpan.FromHours(1)), port)); Assert.Throws<ArgumentException>(() => Invoke(root, observation, Select(EmptyObservation()), port)); Assert.That(port.Calls, Is.Empty); });
        }

        [Test] public void AC005_ReflectionCorruptedSelectionFieldsMakeZeroCalls()
        {
            WithDirectory(root => { var observation = ThreeIntentObservation(); var selection = Select(observation); var mutations = new Dictionary<string, object> { { "_source", (ProfileLaunchSource)99 }, { "_sourceRevision", -999L }, { "_resultRevision", -999L }, { "_inMemoryDocument", default(ProfileCanonicalDocumentV1) }, { "_requiresAtomicSave", !selection.RequiresAtomicSave }, { "_recoveryReasons", (ProfileRecoveryPlanReason)0 }, { "_primaryPreservation", ProfileFilePreservationReason.None }, { "_previousPreservation", ProfileFilePreservationReason.None }, { "_tempPreservation", ProfileFilePreservationReason.None } }; foreach (var mutation in mutations) { var corrupt = Mutate(selection, mutation.Key, mutation.Value); var port = new Port(); Assert.Throws<ArgumentException>(() => Invoke(root, observation, corrupt, port), mutation.Key); Assert.That(port.Calls, Is.Empty, mutation.Key); } });
        }

        [Test] public void AC006_ProtocolViolationsAndExceptionsStopAndNextExecuteWorks()
        {
            WithDirectory(root => { var observation = ThreeIntentObservation(); var selection = Select(observation); Assert.Throws<ArgumentNullException>(() => Invoke(root, observation, selection, null)); foreach (var port in new[] { new Port { MismatchRole = true }, new Port { MismatchReason = true }, new Port { ReturnDefault = true }, new Port { ReturnCorrupt = true }, new Port { ExceptionToThrow = new InvalidOperationException("unexpected") }, new Port { ExceptionToThrow = new OutOfMemoryException("fatal representative") } }) { Assert.Catch<Exception>(() => Invoke(root, observation, selection, port)); Assert.That(port.Calls.Count, Is.EqualTo(1)); } var following = new Port { Outcomes = new[] { ProfileQuarantineOutcome.SourceMissing, ProfileQuarantineOutcome.SourceMissing, ProfileQuarantineOutcome.SourceMissing } }; Assert.That(Invoke(root, observation, selection, following).MayPersist, Is.True); Assert.That(following.Calls.Count, Is.EqualTo(3)); });
        }

        [Test] public void AC007_EveryResultBackingFieldMutationFailsClosedFromGetter()
        {
            WithDirectory(root => { var observation = ThreeIntentObservation(); var valid = Invoke(root, observation, Select(observation), new Port { Outcomes = new[] { ProfileQuarantineOutcome.Preserved, ProfileQuarantineOutcome.Preserved, ProfileQuarantineOutcome.Preserved } }); var mutations = new Dictionary<string, object> { { "_temp", (ProfileLaunchPreservationStateV1)99 }, { "_primary", (ProfileLaunchPreservationStateV1)99 }, { "_previous", (ProfileLaunchPreservationStateV1)99 }, { "_mayPersist", false }, { "_stoppedRole", (ProfileLoadFileRole?)ProfileLoadFileRole.Temp }, { "_tempIntent", ProfileFilePreservationReason.None }, { "_primaryIntent", ProfileFilePreservationReason.None }, { "_previousIntent", ProfileFilePreservationReason.None }, { "_attemptedCount", 99 } }; foreach (var mutation in mutations) { var corrupt = Mutate(valid, mutation.Key, mutation.Value); Assert.Throws<InvalidOperationException>(() => { var unused = corrupt.MayPersist; }, mutation.Key); } });
        }

        [Test] public void AC008_StaticBoundaryHasOneStatelessDelegationAndNoForbiddenAuthority()
        {
            var source = File.ReadAllText(Path.Combine(FindRoot(), "Assets", "AcadeGameMaker", "Runtime", "Profile", "ProfileLaunchPreservationExecutorV1.cs")); Assert.That(Occurrences(source, "ProfileQuarantineServiceV1.Preserve"), Is.EqualTo(1)); StringAssert.Contains("static readonly ProfileLaunchPreservationBclPort Instance", source); foreach (var forbidden in new[] { "ProfileAtomicSave", "SaveInput", "UnityEngine", "persistentDataPath", "DateTime.Now", "Random", "File.Delete", "File.Copy", "ProfileLaunchObservationAdapterV1.Observe" }) StringAssert.DoesNotContain(forbidden, source);
        }

        private static ProfileLaunchPreservationResultV1 Invoke(string root, ProfileLaunchObservationBatchV1 observation, ProfileLoadSelectionPlanV1 selection, Port port) => ProfileLaunchPreservationExecutorV1.Execute(root, observation, selection, Utc, port);
        private static ProfileLoadSelectionPlanV1 Select(ProfileLaunchObservationBatchV1 observation) => ProfileLoadSelectorV1.Select(observation.Primary, observation.Previous, observation.Temp);
        private static ProfileLaunchObservationBatchV1 EmptyObservation() => new ProfileLaunchObservationBatchV1(ProfileLoadCandidateV1.Missing(ProfileLoadFileRole.Primary), ProfileLoadCandidateV1.Missing(ProfileLoadFileRole.Previous), ProfileLoadCandidateV1.Missing(ProfileLoadFileRole.Temp));
        private static ProfileLaunchObservationBatchV1 ThreeIntentObservation() => new ProfileLaunchObservationBatchV1(InvalidCandidate(ProfileLoadFileRole.Primary), UnsupportedCandidate(ProfileLoadFileRole.Previous), InvalidCandidate(ProfileLoadFileRole.Temp));
        private static ProfileLoadCandidateV1 InvalidCandidate(ProfileLoadFileRole role) => ProfileLoadCandidateV1.Decoded(role, ProfileCanonicalDecoderV1.Decode(Encoding.UTF8.GetBytes("{}")));
        private static ProfileLoadCandidateV1 UnsupportedCandidate(ProfileLoadFileRole role) => ProfileLoadCandidateV1.Decoded(role, ProfileCanonicalDecoderV1.Decode(Encoding.UTF8.GetBytes("{\"schemaVersion\":0}")));
        private static void AssertStates(ProfileLaunchPreservationResultV1 result, ProfileLaunchPreservationStateV1 temp, ProfileLaunchPreservationStateV1 primary, ProfileLaunchPreservationStateV1 previous, bool mayPersist, ProfileLoadFileRole? stopped) { Assert.That(result.TempState, Is.EqualTo(temp)); Assert.That(result.PrimaryState, Is.EqualTo(primary)); Assert.That(result.PreviousState, Is.EqualTo(previous)); Assert.That(result.MayPersist, Is.EqualTo(mayPersist)); Assert.That(result.StoppedRole, Is.EqualTo(stopped)); }
        private static void AssertCandidateEqual(ProfileLoadCandidateV1 expected, ProfileLoadCandidateV1 actual) { Assert.That(actual.Role, Is.EqualTo(expected.Role)); Assert.That(actual.Kind, Is.EqualTo(expected.Kind)); if (expected.Kind != ProfileLoadCandidateKind.Decoded) return; Assert.That(actual.DecodeResult.Classification, Is.EqualTo(expected.DecodeResult.Classification)); if (expected.DecodeResult.Classification == ProfileCanonicalDecodeClassification.UnsupportedProfileSchema) Assert.That(actual.DecodeResult.UnsupportedSchemaVersion, Is.EqualTo(expected.DecodeResult.UnsupportedSchemaVersion)); }
        private static T Mutate<T>(T value, string fieldName, object fieldValue) where T : struct { object boxed = value; typeof(T).GetField(fieldName, BindingFlags.Instance | BindingFlags.NonPublic).SetValue(boxed, fieldValue); return (T)boxed; }
        private static string Hash8(byte[] bytes) { using (var sha = SHA256.Create()) { var hash = sha.ComputeHash(bytes); var builder = new StringBuilder(8); for (var i = 0; i < 4; i++) builder.Append(hash[i].ToString("x2")); return builder.ToString(); } }
        private static int Occurrences(string text, string value) { var count = 0; var index = 0; while ((index = text.IndexOf(value, index, StringComparison.Ordinal)) >= 0) { count++; index += value.Length; } return count; }
        private static void WithDirectory(Action<string> action) { var root = Path.Combine(Path.GetTempPath(), "AcadeGameMaker-M5D7K-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(root); try { action(root); } finally { if (Directory.Exists(root)) Directory.Delete(root, true); } }
        private static string FindRoot() { var current = new DirectoryInfo(TestContext.CurrentContext.TestDirectory); while (current != null) { if (File.Exists(Path.Combine(current.FullName, "Packages", "manifest.json"))) return current.FullName; current = current.Parent; } throw new DirectoryNotFoundException(); }

        internal sealed class Port : IProfileLaunchPreservationPort
        {
            internal readonly List<string> Calls = new List<string>(); internal readonly List<string> Roots = new List<string>(); internal readonly List<DateTimeOffset> UtcCalls = new List<DateTimeOffset>(); internal readonly List<ProfileLoadCandidateV1> Candidates = new List<ProfileLoadCandidateV1>(); internal readonly List<ProfileQuarantineResultV1> Returned = new List<ProfileQuarantineResultV1>();
            internal ProfileQuarantineOutcome[] Outcomes; internal bool MismatchRole; internal bool MismatchReason; internal bool ReturnDefault; internal bool ReturnCorrupt; internal bool FailedSourceUnreadable; internal Exception ExceptionToThrow;
            public ProfileQuarantineResultV1 Preserve(string root, ProfileLoadCandidateV1 candidate, ProfileFilePreservationReason reason, DateTimeOffset utc) { Candidates.Add(candidate); Calls.Add(candidate.Role + ":" + reason); Roots.Add(root); UtcCalls.Add(utc); if (ExceptionToThrow != null) throw ExceptionToThrow; if (ReturnDefault) return default(ProfileQuarantineResultV1); var role = MismatchRole ? (candidate.Role == ProfileLoadFileRole.Temp ? ProfileLoadFileRole.Primary : ProfileLoadFileRole.Temp) : candidate.Role; var returnedReason = MismatchReason ? (reason == ProfileFilePreservationReason.StaleTemp ? ProfileFilePreservationReason.InvalidPrimary : ProfileFilePreservationReason.StaleTemp) : reason; var outcome = Outcomes == null ? ProfileQuarantineOutcome.SourceMissing : Outcomes[Calls.Count - 1]; var result = MakeResult(root, role, returnedReason, outcome, FailedSourceUnreadable); result = ReturnCorrupt ? Mutate(result, "_reason", ProfileFilePreservationReason.None) : result; Returned.Add(result); return result; }
            private static ProfileQuarantineResultV1 MakeResult(string root, ProfileLoadFileRole role, ProfileFilePreservationReason reason, ProfileQuarantineOutcome outcome, bool failedSourceUnreadable) { if (outcome == ProfileQuarantineOutcome.SourceMissing) return new ProfileQuarantineResultV1(outcome, ProfileQuarantineStage.SourceRevalidation, role, reason, ProfileQuarantineFileState.Missing, ProfileQuarantineFileState.NotProbed, string.Empty, string.Empty, -1, null, null, null, false); if (outcome == ProfileQuarantineOutcome.FailedBeforeMove) return new ProfileQuarantineResultV1(outcome, ProfileQuarantineStage.SourceRevalidation, role, reason, failedSourceUnreadable ? ProfileQuarantineFileState.Unreadable : ProfileQuarantineFileState.Present, ProfileQuarantineFileState.NotProbed, string.Empty, string.Empty, -1, null, null, null, false); var suffix = reason == ProfileFilePreservationReason.StaleTemp || reason == ProfileFilePreservationReason.UnreadablePrimary || reason == ProfileFilePreservationReason.UnreadablePrevious ? "nohash" : "00000000"; var unsupported = reason == ProfileFilePreservationReason.UnsupportedPrimary || reason == ProfileFilePreservationReason.UnsupportedPrevious ? (int?)0 : null; return new ProfileQuarantineResultV1(outcome, outcome == ProfileQuarantineOutcome.Preserved ? ProfileQuarantineStage.None : ProfileQuarantineStage.MoveCall, role, reason, ProfileQuarantineFileState.Missing, ProfileQuarantineFileState.Present, Path.Combine(root, "recovery", Stem(role, reason, suffix) + ".json"), suffix, 0, root, UtcToken, unsupported, suffix != "nohash"); }
            private static string Stem(ProfileLoadFileRole role, ProfileFilePreservationReason reason, string suffix) { if (reason == ProfileFilePreservationReason.StaleTemp) return "profile-stale-temp-" + UtcToken + "-" + suffix; if (reason == ProfileFilePreservationReason.InvalidPrimary) return "profile-invalid-primary-" + UtcToken + "-" + suffix; if (reason == ProfileFilePreservationReason.InvalidPrevious) return "profile-invalid-previous-" + UtcToken + "-" + suffix; if (reason == ProfileFilePreservationReason.UnsupportedPrimary || reason == ProfileFilePreservationReason.UnsupportedPrevious) return "profile-unsupported-v0-" + UtcToken + "-" + suffix; return "profile-unreadable-" + (role == ProfileLoadFileRole.Primary ? "primary" : "previous") + "-" + UtcToken + "-" + suffix; }
        }
    }
}
